import {properties,sources,csv} from './model.mjs';
import {marketingChannel,marketingHistory,summarizeMarketingTouches,validMarketingRange,marketingExportRows} from './marketing-touchpoints.mjs';
import {stages,channels,leadTags,leadTagName,setLeadTag,prospect,stageName,pipelineRecords,interactionHistory,contactStats,addInteraction,scheduleTour} from './prospects.mjs';

export function createLeasingWorkspace(api){
 const {esc,btn,chip,heading,panel,metric,icon,money,pName,sName,filters,getState,render,navigate,persist,toast}=api;
 let marketingSource='all',marketingFrom='',marketingTo='';
 let search='',source='all',tag='all',page=0,expandedId=null,recordTab='timeline',channel='all',direction='all',composeChannel='Email',composeDirection='outbound',returnRoute='pipeline/all';
 const s=()=>getState();
 const dt=value=>new Intl.DateTimeFormat('en-CA',{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short'}).format(new Date(value));
 const field=(label,value)=>`<div><dt>${label}</dt><dd>${esc(value??'Not recorded')}</dd></div>`;
 const details=items=>`<dl class="record-fields">${items.map(([k,v])=>field(k,v)).join('')}</dl>`;
 const stageButton=(id,label,value,property)=>`<button type="button" class="stage-card" data-action="drill-stage" data-stage="${id}" ${property?`data-property="${property}"`:''}><span>${label}</span><strong>${value}</strong><small>View records ${icon('arrow',13)}</small></button>`;
 function stageCards(m,property){return `<div class="stage-grid">${stages.map(([id,label])=>stageButton(id,label,id==='all'?m.leads.length:id==='leased'?m.leases:m[id],property)).join('')}</div>`;}
 function tagControl(l){return `<div class="lead-tag-field"><label for="lead-tag-${l.id}">Lead tag<span class="sr-only"> for ${esc(l.name)} (${l.id})</span></label><select id="lead-tag-${l.id}" data-lead-tag data-id="${l.id}" class="lead-tag tag-${l.tag}">${leadTags.map(([id,label])=>`<option value="${id}" ${l.tag===id?'selected':''}>${label}</option>`).join('')}</select></div>`;}
 function quickDetails(l,stats){return `<div class="lead-quick-details" id="lead-details-${l.id}"><h3>${esc(l.name)} · Lead details</h3>${details([['Email',l.email],['Phone',l.phone],['Enquiry date',l.created],['Preferred move-in',l.moveIn],['Bedrooms',l.bedrooms],['Monthly budget',money(l.budget)],['Preferred channel',l.preferredChannel],['Next / completed tour',l.tour?l.tour.date+' · '+l.tour.status:'Not scheduled']])}${stats.last?`<div class="lead-last-contact"><strong>Last interaction · ${esc(stats.last.channel)} · ${stats.last.direction==='inbound'?'Incoming':'Outgoing'}</strong><span>${dt(stats.last.at)}</span><p>${esc(stats.last.subject)}</p></div>`:''}${btn('Open full record '+icon('arrow',14),'open-prospect',`data-id="${l.id}"`,'secondary small')}</div>`;}
 function listTable(rows){return `<div class="lead-list-wrap"><table class="lead-list" role="table"><caption class="sr-only">Leads with leasing stage, editable tag, contact counts and record details</caption><thead><tr><th scope="col">Lead</th><th scope="col">Property / source</th><th scope="col">Leasing stage</th><th scope="col">Lead tag</th><th scope="col">Interactions</th><th scope="col">Owner</th><th scope="col"><span class="sr-only">Actions</span></th></tr></thead><tbody>${rows.map(l=>{const stats=contactStats(l.id,s()),expanded=expandedId===l.id;return `<tr class="lead-list-row ${expanded?'expanded':''}"><td class="lead-identity" data-label="Lead"><button class="link prospect-name" data-action="open-prospect" data-id="${l.id}">${esc(l.name)}</button><small>${l.contactId} · ${l.id}</small></td><td data-label="Property / source"><strong>${esc(pName(l.property))}</strong><small>${esc(sName(l.source))}</small></td><td data-label="Leasing stage">${chip(stageName(l),l.leased?'good':'info')}</td><td class="lead-tag-cell">${tagControl(l)}</td><td data-label="Interactions"><strong>${stats.total} total</strong><small>${stats.inbound} inbound · ${stats.outbound} outbound</small></td><td data-label="Owner">${esc(l.owner)}</td><td class="lead-list-actions">${btn(expanded?'Hide details':'Details','pipeline-expand',`data-id="${l.id}" aria-expanded="${expanded}" aria-controls="lead-details-${l.id}" aria-label="${expanded?'Hide':'Show'} details for ${esc(l.name)} (${l.id})"`,'secondary small')}${btn('Open record '+icon('arrow',12),'open-prospect',`data-id="${l.id}" aria-label="Open record for ${esc(l.name)} (${l.id})"`,'ghost small')}</td></tr><tr class="lead-detail-row" ${expanded?'':'hidden'}><td colspan="7">${expanded?quickDetails(l,stats):`<div id="lead-details-${l.id}"></div>`}</td></tr>`;}).join('')}</tbody></table></div>`;}
 function list(stage='all',communications=false){
  if(!stages.some(([x])=>x===stage))stage='all';
  const list=pipelineRecords(filters,s(),{stage,search,source,tag});
  if(communications)list.sort((a,b)=>(contactStats(b.id,s()).last?.at||'').localeCompare(contactStats(a.id,s()).last?.at||''));
  page=Math.max(0,Math.min(page,Math.max(0,Math.ceil(list.length/12)-1)));
  const rows=list.slice(page*12,page*12+12),view=s().leadView==='list'?'list':'cards';
  const switcher=`<div class="lead-display-toolbar"><p>Lead tags are editable and separate from leasing stages.</p><div class="lead-view-switch" role="group" aria-label="Lead display format">${[['cards','Cards'],['list','List / detail']].map(([id,label])=>btn(label,'pipeline-view',`data-view="${id}" aria-pressed="${view===id}"`,view===id?'selected':'secondary')).join('')}</div></div>`;
  const toolbar=`<div class="record-toolbar"><div class="field"><label for="pipeline-search">Search leads</label><input id="pipeline-search" placeholder="Name, ID, email, phone or property" value="${esc(search)}"></div><div class="field"><label for="pipeline-source">Original source</label><select id="pipeline-source"><option value="all">All sources</option>${sources.map(x=>`<option value="${x.id}" ${source===x.id?'selected':''}>${x.name}</option>`).join('')}</select></div><div class="field"><label for="pipeline-tag">Lead tag</label><select id="pipeline-tag"><option value="all">All tags</option>${leadTags.map(([id,label])=>`<option value="${id}" ${tag===id?'selected':''}>${label}</option>`).join('')}</select></div>${btn(icon('download')+' Export records','pipeline-export',`data-stage="${stage}"`,'secondary')}</div>`;
  const cards=()=>`<div class="prospect-grid">${rows.map(l=>{const stats=contactStats(l.id,s());return `<article class="prospect-card"><div class="prospect-card-top"><span class="avatar teal">${esc(l.name.split(' ').map(x=>x[0]).join(''))}</span><div><button class="link prospect-name" data-action="open-prospect" data-id="${l.id}">${esc(l.name)}</button><small>${l.contactId} · ${l.id}</small></div>${chip(stageName(l),l.leased?'good':'info')}</div>${tagControl(l)}<div class="prospect-summary"><strong>${pName(l.property)}</strong><small>${sName(l.source)} · Enquired ${l.created}</small></div><div class="contact-counts"><span><strong>${stats.total}</strong> interactions</span><span><strong>${stats.inbound}</strong> inbound</span><span><strong>${stats.outbound}</strong> outbound</span></div><p class="last-message">${communications&&stats.last?esc(stats.last.subject):`${l.bedrooms} bedrooms · ${money(l.budget)} budget · ${esc(l.owner)}`}</p><div class="prospect-card-bottom"><small>${stats.last?dt(stats.last.at):'No activity'}</small>${btn('Open record '+icon('arrow',14),'open-prospect',`data-id="${l.id}"`,'secondary small')}</div></article>`;}).join('')}</div>`;
  return heading(communications?'Every conversation. One shared history.':'Lead to Lease',communications?'Email, SMS, calls, chat and visits stay linked to the same prospect.':'Manage every lead, set follow-up priority and track the journey from enquiry to signed lease.',btn('Portfolio overview','navigate','data-route="portfolio"','secondary'),communications?'Communications':'Leasing')+`<div class="insight">${icon('info')}<span>${communications?'Demo communications are saved in this browser. No messages are delivered and no live inboxes or phone lines are connected.':'Counts are cumulative milestones for the selected enquiry cohort. A signed lease also appears in applications and completed tours.'}</span></div>`+(!communications?`<nav class="tabs" aria-label="Leasing stages">${stages.map(([id,label])=>btn(label,'drill-stage',`data-stage="${id}" ${stage===id?'aria-current="page"':''}`,`stage-tab ${stage===id?'selected':'secondary'}`)).join('')}</nav>`:'')+panel(`${communications?'Conversations':stages.find(([x])=>x===stage)[1]} · ${list.length} leads`,'Your property, city, management company and cohort filters remain active.',switcher+toolbar+(rows.length?(view==='list'?listTable(rows):cards()):`<div class="empty"><h3>No matching leads</h3><p>Change the search or filters to see more records.</p>${btn('Reset record search','pipeline-reset','','secondary')}</div>`)+`<div class="pagination"><span>${list.length?page*12+1:0}–${Math.min(list.length,(page+1)*12)} of ${list.length}</span><div>${btn('Previous','pipeline-page',`data-delta="-1" ${page===0?'disabled':''}`,'secondary small')}${btn('Next','pipeline-page',`data-delta="1" ${(page+1)*12>=list.length?'disabled':''}`,'secondary small')}</div></div>`);
 }
 function timeline(l){const events=interactionHistory(l.id,s()).filter(x=>(channel==='all'||x.channel===channel)&&(direction==='all'||x.direction===direction));return `<div class="record-toolbar compact"><label>Channel <select id="timeline-channel"><option value="all">All channels</option>${channels.map(x=>`<option ${x===channel?'selected':''}>${x}</option>`).join('')}</select></label><label>Direction <select id="timeline-direction">${[['all','All directions'],['inbound','Inbound'],['outbound','Outbound'],['internal','Internal notes']].map(([id,label])=>`<option value="${id}" ${id===direction?'selected':''}>${label}</option>`).join('')}</select></label><small>${events.length} records</small>${btn('Export history','history-export',`data-id="${l.id}"`,'secondary small')}</div><p class="footnote">Newest first · timestamps shown in your local timezone · notes and drafts are excluded from interaction counts.</p><ol class="conversation-timeline">${events.map(x=>`<li class="interaction ${x.direction}"><div class="interaction-head"><span class="channel-icon">${icon(x.channel==='Phone'?'people':x.channel==='Note'?'tasks':'message',16)}</span><strong>${esc(x.channel)} · ${x.direction==='inbound'?'Incoming':x.direction==='outbound'?'Outgoing':'Internal'}</strong><time datetime="${x.at}">${dt(x.at)}</time></div><h3>${esc(x.subject)}</h3><p>${esc(x.body)}</p><div class="interaction-footer"><small>${esc(x.agent)}${x.channel==='Phone'&&x.handledBy?' · Handled by '+esc(x.handledBy):''}${x.duration?` · ${Math.round(x.duration/60)} min`:''}${x.outcome?' · '+esc(x.outcome):''}</small>${chip(x.status)}</div><small class="interaction-id">${esc(x.id)}</small></li>`).join('')||'<li class="empty">No interactions match these filters.</li>'}</ol>`;}
 function composer(l){const log=['Phone','Visit','Note'].includes(composeChannel),internal=composeChannel==='Note';return `<form id="communication-form" data-id="${l.id}"><div class="record-toolbar compact"><div class="field"><label for="compose-channel">Channel</label><select id="compose-channel" name="channel">${channels.map(x=>`<option ${x===composeChannel?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="compose-direction">Direction</label><select id="compose-direction" name="direction">${(internal?[['internal','Internal note']]:[['outbound','Outgoing'],['inbound','Incoming demo']]).map(([id,label])=>`<option value="${id}" ${composeDirection===id?'selected':''}>${label}</option>`).join('')}</select></div></div><div class="recipient-strip"><strong>${esc(l.name)}</strong><span>${esc(composeChannel==='Email'?l.email:l.phone)} · Fictional contact</span></div><div class="field"><label for="message-subject">${log?'Interaction title':'Subject / topic'}</label><input id="message-subject" name="subject" maxlength="140" required placeholder="${log?'Follow-up call about availability':'Follow-up on your enquiry'}"></div><div class="field"><label for="message-body">${log?'Notes / conversation summary':'Message'}</label><textarea id="message-body" name="body" maxlength="5000" required placeholder="${log?'Record the discussion, outcome and next step…':'Write your message…'}"></textarea></div>${['Phone','Visit'].includes(composeChannel)?`<div class="record-toolbar compact"><div class="field"><label for="call-duration">Duration (minutes)</label><input id="call-duration" name="minutes" type="number" min="0" max="1440" value="5"></div><div class="field"><label for="call-outcome">Outcome</label><select id="call-outcome" name="outcome">${['Connected','Voicemail','No answer','Completed','Follow-up required'].map(x=>`<option>${x}</option>`).join('')}</select></div></div>`:''}<div class="notice">${composeChannel==='Phone'?'Call logging only. Calling, audio recording and transcription need a telephony provider.':composeDirection==='inbound'?'Simulate an incoming message to demonstrate the shared history. Live inbox capture needs a provider connection.':'Demo only. This records the interaction locally; nothing is sent to the prospect.'}</div><p id="communication-error" class="form-error" role="alert"></p><button class="btn" type="submit">${log?'Save interaction':composeDirection==='inbound'?'Record incoming demo':'Send demo message'}</button></form>`;}
 function recordDetails(l){return panel('Enquiry & contact','A single contact ID links every channel and milestone.',details([['Contact ID',l.contactId],['Enquiry ID',l.id],['Lead tag',leadTagName(l.tag)],['Email',l.email],['Phone',l.phone],['Created',l.created],['Preferred channel',l.preferredChannel],['Assigned owner',l.owner],['Original source',sName(l.source)],['Campaign',l.campaign],['UTM source',l.utmSource],['UTM medium',l.utmMedium],['Bedrooms',l.bedrooms],['Budget / month',money(l.budget)],['Preferred move-in',l.moveIn],['Property',pName(l.property)],['Contact consent','Demo placeholder · verify before live outreach']]))+panel('Record provenance','Fictional demonstration data.',`<p class="muted">Prospects are linked by a stable contact ID, not by matching names. Original-source attribution remains separate from the multi-channel interaction history. Live identity matching, consent records and provider delivery receipts require integrations.</p>`);}
 function tourPanel(l){return panel('Tour details','Appointments remain linked to the original enquiry.',l.tour?details([['Tour ID','TOUR-'+l.id],['Status',l.tour.status],['Date',l.tour.date],['Time',l.tour.time+' · property local time'],['Tour type',l.tour.type],['Leasing host',l.tour.host],['Unit / home',l.tour.unit],['Notes',l.tour.notes]])+`<p class="footnote">The original demo snapshot is through Nov 13, 2026. A scheduled tour does not imply it was completed.</p>`:`<form id="tour-form" data-id="${l.id}"><div class="empty compact-empty"><h3>No tour scheduled</h3><p>Book a sample appointment and record its confirmation in the contact history.</p></div><div class="record-toolbar"><div class="field"><label for="tour-date">Date</label><input id="tour-date" name="date" type="date" min="${new Date().toISOString().slice(0,10)}" required></div><div class="field"><label for="tour-time">Time (property local)</label><input id="tour-time" name="time" type="time" value="14:00" required></div><div class="field"><label for="tour-type">Tour type</label><select id="tour-type" name="type"><option>In person</option><option>Virtual</option></select></div></div><div class="field"><label for="tour-notes">Appointment notes</label><textarea id="tour-notes" name="notes" maxlength="1000" placeholder="Meeting point or accessibility requests for the sample appointment"></textarea></div><p class="form-error" id="tour-error" role="alert"></p><button type="submit" class="btn">Book demo tour</button><p class="footnote">Updates the scheduled-tour count and logs a demo confirmation. No external calendar invitation is sent.</p></form>`);}
 function applicationPanel(l){return panel('Application details','Application status is shown independently of the tour.',l.application?details([['Application ID',l.application.id],['Received',l.application.received],['Status',l.application.status],['Applicants',l.application.applicants],['Requested unit',l.unit],['Preferred move-in',l.moveIn]])+`<h3>Document checklist</h3><div class="document-list">${l.application.documents.map(([name,status])=>`<div class="row"><span>${name}</span>${chip(status)}</div>`).join('')}</div><p class="notice">${l.application.note}</p>`:`<div class="empty"><h3>No application received</h3><p>This prospect has not reached the application milestone.</p>${btn('Open conversations','record-tab','data-tab="compose"','secondary')}</div>`);}
 function leasePanel(l){return panel('Lease details','Signed lease metadata and move-in handoff.',l.lease?details([['Lease ID',l.lease.id],['Status',l.lease.status],['Signed',l.lease.signed],['Lease start',l.lease.start],['Lease end',l.lease.end],['Monthly rent',money(l.lease.rent)],['Term',l.lease.term],['Unit / home',l.unit],['Property',pName(l.property)],['Days from enquiry',l.days],['Linked application',l.application.id],['Document',l.lease.document]]):`<div class="empty"><h3>No signed lease</h3><p>A lease record will appear here when the signed-lease milestone is recorded.</p>${btn('View application','record-tab','data-tab="application"','secondary')}</div>`);}
 const touchDate=value=>value?new Intl.DateTimeFormat('en-CA',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}).format(new Date(value)):'Not recorded';
 const touchFilters=()=>({channel:marketingSource,from:marketingFrom,to:marketingTo});
 function marketingSummary(l){const summary=summarizeMarketingTouches(marketingHistory(l.id));return panel('Marketing touchpoints',`${esc(pName(l.property))} · This contact’s recorded marketing history, including before the enquiry.`,`<div class="touchpoint-summary-stats"><div><span>Marketing touches</span><strong>${summary.total}</strong><small>Recorded visits, referrals & enquiries</small></div><div><span>Marketing channels</span><strong>${summary.channelCount}</strong><small>${summary.repeats} repeat touches across these channels</small></div><div><span>First recorded touch</span><strong class="touchpoint-date">${touchDate(summary.first?.at)}</strong><small>${esc(marketingChannel(summary.first?.channel)?.name||'Not recorded')}</small></div><div><span>Latest recorded touch</span><strong class="touchpoint-date">${touchDate(summary.last?.at)}</strong><small>${esc(marketingChannel(summary.last?.channel)?.name||'Not recorded')}</small></div></div><div class="touchpoint-channel-pills">${summary.channels.map(c=>btn(`<span class="touchpoint-dot touchpoint-${c.id}"></span>${esc(c.name)}<strong>×${c.count}</strong>`,'marketing-channel',`data-channel="${c.id}" aria-label="View ${c.count} marketing touchpoints from ${esc(c.name)}"`,'secondary small')).join('')}</div><p class="touchpoint-footnote">Fictional demo history · Separate from calls, emails and texts. Original-source attribution remains ${esc(sName(l.source))}.</p>`,btn('View marketing journey '+icon('arrow',13),'marketing-channel','data-channel="all"','secondary small'),'full touchpoint-overview');}
 function marketingJourney(l){
  const valid=validMarketingRange(touchFilters()),events=marketingHistory(l.id,touchFilters()),summary=summarizeMarketingTouches(events),all=summarizeMarketingTouches(marketingHistory(l.id));
  const controls=`<div class="record-toolbar touchpoint-filters"><div class="field"><label for="marketing-source">Marketing channel</label><select id="marketing-source"><option value="all">All channels</option>${all.channels.map(c=>`<option value="${c.id}" ${marketingSource===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label for="marketing-from">From</label><input type="date" id="marketing-from" value="${esc(marketingFrom)}"></div><div class="field"><label for="marketing-to">To</label><input type="date" id="marketing-to" value="${esc(marketingTo)}"></div>${btn('All history','marketing-reset','','secondary small')}${btn('Export touchpoints','marketing-export',`data-id="${l.id}" ${!events.length||!valid?'disabled':''}`,'secondary small')}</div>${!valid?'<p class="form-error" role="alert">Choose valid dates, with the end date on or after the start date.</p>':''}`;
  const breakdown=summary.channels.map(c=>`<div class="touchpoint-channel-card"><div><span class="touchpoint-dot touchpoint-${c.id}"></span><strong>${esc(c.name)}</strong><span class="touchpoint-count">${c.count} ${c.count===1?'touch':'touches'}</span></div><div class="touchpoint-channel-track"><span class="touchpoint-${c.id}" style="width:${c.count/summary.total*100}%"></span></div><p>${c.repeats} repeat ${c.repeats===1?'touch':'touches'} · ${esc(c.group)}</p><small>First ${touchDate(c.first.at)}<br>Latest ${touchDate(c.last.at)}</small></div>`).join('');
  const timeline=events.map((event,i)=>`<li><span class="touchpoint-dot touchpoint-${event.channel}"></span><div class="touchpoint-touch-header"><strong>${esc(marketingChannel(event.channel).name)}</strong><time datetime="${event.at}">${dt(event.at)}</time></div><h3>${esc(event.eventType)}</h3><p>${esc(event.campaign)} · ${esc(event.medium.replaceAll('_',' '))}</p><div class="touchpoint-touch-flags">${i===0?chip('First in selection','info'):''}${i===events.length-1?chip('Latest in selection','info'):''}${chip('Demo event')}</div><details class="touchpoint-evidence"><summary>Touchpoint details</summary>${details([['Event ID',event.id],['Linked contact',event.contactId],['Property',pName(event.property)],['Captured via',event.capture],['Identity link',event.linkMethod],['Landing page',event.landingPage],['Campaign',event.campaign],['Source / medium',marketingChannel(event.channel).name+' / '+event.medium]])}</details></li>`).join('');
  return panel('Marketing journey',`${esc(pName(l.property))} · ${l.contactId} · Chronological history across marketing sources.`,controls+`<div class="touchpoint-selection"><strong>${summary.total} ${summary.total===1?'touchpoint':'touchpoints'} · ${summary.channelCount} ${summary.channelCount===1?'channel':'channels'}</strong><span>${events.length?touchDate(summary.first.at)+' – '+touchDate(summary.last.at):'No activity in this selection'}</span></div>`+(events.length?`<div class="touchpoint-channel-grid">${breakdown}</div><h3 class="touchpoint-timeline-title">Touchpoint timeline</h3><p class="touchpoint-footnote">Oldest first · Each recorded event counts once; repeat visits remain separate touches.</p><ol class="touchpoint-timeline">${timeline}</ol>`:`<div class="empty"><h3>No recorded marketing touches${valid?' in this selection':''}</h3><p>${valid?'Try another channel or date range. Missing activity is not proof that the person never visited a channel.':'Correct the date range to see this contact’s history.'}</p>${btn('Show all history','marketing-reset','','secondary')}</div>`)+`<div class="notice"><strong>Demo data — live tracking is not connected.</strong> A production journey combines captured website visits, tagged referrals and lead-provider events linked to a known contact and property. Anonymous activity and unshared third-party browsing are not shown as identified touches. Marketing touches do not add enquiries or change your original-source attribution.</div>`);
 }
 function detail(id){const l=prospect(id,s());if(!l)return heading('Prospect not found','This record is not in the demo dataset.',btn('Back to enquiries','navigate','data-route="pipeline/all"'));const stats=contactStats(id,s());const tabs=[['timeline','Interaction history'],['marketing','Marketing journey'],['details','Contact & enquiry'],['tour','Tour'],['application','Application'],['lease','Lease'],['compose','New interaction']];return `<div class="record-breadcrumb">${btn('← Back to records','navigate',`data-route="${returnRoute}"`,'ghost')}<span>${pName(l.property)} / ${l.contactId}</span></div>`+heading(esc(l.name),`${l.contactId} · ${l.id} · Fictional prospect`,`<div class="lead-badges">${chip(stageName(l),l.leased?'good':'info')}<span class="lead-tag tag-${l.tag}">${leadTagName(l.tag)}</span></div>`,'Prospect 360')+`<div class="metrics record-metrics">${metric('Total interactions',stats.total,'All recorded contact channels','message')}${metric('Inbound contacts',stats.inbound,'Times the prospect got in touch','people')}${metric('Outbound follow-ups',stats.outbound,'Leasing team interactions','arrow')}${metric('Contact channels',stats.channels.length,stats.channels.join(' · '),'globe')}</div>${marketingSummary(l)}<div class="prospect-layout"><aside class="panel contact-panel"><div class="profile-avatar">${esc(l.name.split(' ').map(x=>x[0]).join(''))}</div><h2>${esc(l.name)}</h2><p>${pName(l.property)}</p>${details([['Email',l.email],['Phone',l.phone],['Original source',sName(l.source)],['Preferred channel',l.preferredChannel]])}${tagControl(l)}<div class="field"><label for="prospect-owner">Leasing owner</label><select id="prospect-owner" data-id="${l.id}">${properties.map(p=>`<option ${p.owner===l.owner?'selected':''}>${p.owner}</option>`).join('')}</select></div>${btn(icon('message')+' New interaction','record-tab','data-tab="compose"')}${btn('Create follow-up task','task',`data-key="lead-${l.id}" data-property="${l.property}" data-title="Follow up with ${esc(l.name)}"`,'secondary')}<div class="milestone-list">${[['Enquiry received',true],['Tour scheduled',l.scheduled],['Tour completed',l.toured],['Application received',l.applied],['Lease signed',l.leased]].map(([name,done])=>`<div class="${done?'reached':''}"><span>${done?'✓':'○'}</span>${name}</div>`).join('')}</div><p class="footnote">Same contact across every interaction. Names are never used to merge people automatically.</p></aside><div class="record-main"><nav class="tabs record-tabs" aria-label="Prospect detail views">${tabs.map(([id,label])=>btn(label,'record-tab',`data-tab="${id}" ${recordTab===id?'aria-current="page"':''}`,recordTab===id?'selected':'secondary')).join('')}</nav>${recordTab==='marketing'?marketingJourney(l):recordTab==='details'?recordDetails(l):recordTab==='tour'?tourPanel(l):recordTab==='application'?applicationPanel(l):recordTab==='lease'?leasePanel(l):recordTab==='compose'?panel('Record the next conversation','One workspace for inbound and outbound activity.',composer(l)):panel('Complete interaction history','Every touchpoint, with direction, owner and timestamp.',timeline(l))}</div></div>`;}
 function download(rows,name){const url=URL.createObjectURL(new Blob(['\uFEFF'+csv(rows)],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('CSV exported.');}
 function exportList(stage){const ls=pipelineRecords(filters,s(),{stage,search,source,tag});download([['Contact ID','Enquiry ID','Name','Property','Email','Phone','Original source','Stage','Lead tag','Owner','Created','Tour date','Application ID','Lease ID','Total interactions','Inbound','Outbound'],...ls.map(l=>{const c=contactStats(l.id,s());return [l.contactId,l.id,l.name,pName(l.property),l.email,l.phone,sName(l.source),stageName(l),leadTagName(l.tag),l.owner,l.created,l.tour?.date,l.application?.id,l.lease?.id,c.total,c.inbound,c.outbound];})],`MF-Hub-${stage}-records`);}
 return {stageCards,list,detail,exportList,
  open(id){marketingSource='all';marketingFrom=marketingTo='';recordTab='timeline';channel=direction='all';if(!location.hash.startsWith('#prospect/'))returnRoute=location.hash.slice(1)||'pipeline/all';navigate('prospect/'+id);},
  action(b){const {action,id}=b.dataset;if(action==='drill-stage'){if(b.dataset.property)Object.assign(filters,{property:b.dataset.property,pmc:'all',city:'all'});search='';source=tag='all';page=0;expandedId=null;navigate('pipeline/'+(b.dataset.stage||'all'));}else if(action==='open-prospect')this.open(id);else if(action==='pipeline-view'){if(['cards','list'].includes(b.dataset.view)){s().leadView=b.dataset.view;persist();render();document.querySelector(`[data-action="pipeline-view"][data-view="${s().leadView}"]`)?.focus();}}else if(action==='pipeline-expand'){expandedId=expandedId===id?null:id;render();document.querySelector(`[data-action="pipeline-expand"][data-id="${id}"]`)?.focus();}else if(action==='pipeline-page'){page+=Number(b.dataset.delta);render();}else if(action==='pipeline-reset'){search='';source=tag='all';page=0;expandedId=null;render();}else if(action==='record-tab'){recordTab=b.dataset.tab;render();document.querySelector('.record-main')?.scrollIntoView({block:'start',behavior:'smooth'});}else if(action==='pipeline-export')exportList(b.dataset.stage||'all');else if(action==='marketing-channel'){marketingSource=b.dataset.channel||'all';marketingFrom=marketingTo='';recordTab='marketing';render();document.querySelector('.record-main')?.scrollIntoView({block:'start',behavior:'smooth'});}else if(action==='marketing-reset'){marketingSource='all';marketingFrom=marketingTo='';render();}else if(action==='marketing-export'){if(validMarketingRange(touchFilters()))download(marketingExportRows(marketingHistory(id,touchFilters())),`MF-Hub-${id}-marketing-touchpoints`);}else if(action==='history-export'){const events=interactionHistory(id,s()).filter(x=>(channel==='all'||x.channel===channel)&&(direction==='all'||x.direction===direction));download([['Interaction ID','Contact ID','Date UTC','Direction','Channel','Subject','Body','Owner','Status','Duration seconds','Outcome'],...events.map(x=>[x.id,x.contactId,x.at,x.direction,x.channel,x.subject,x.body,x.agent,x.status,x.duration,x.outcome])],`MF-Hub-${id}-interactions`);}else return false;return true;},
  change(el){const form=document.getElementById('communication-form');const draft=form?Object.fromEntries(new FormData(form)):null;if(el.id==='marketing-source'){marketingSource=el.value;}else if(el.id==='marketing-from'){marketingFrom=el.value;}else if(el.id==='marketing-to'){marketingTo=el.value;}else if(el.id==='pipeline-source'){source=el.value;page=0;expandedId=null;}else if(el.id==='pipeline-tag'){tag=el.value;page=0;expandedId=null;}else if(el.dataset.leadTag!==undefined){try{setLeadTag(s(),el.dataset.id,el.value);persist();toast('Lead tag updated.');}catch(error){toast(error.message);}}else if(el.id==='timeline-channel')channel=el.value;else if(el.id==='timeline-direction')direction=el.value;else if(el.id==='compose-channel'){composeChannel=el.value;composeDirection=el.value==='Note'?'internal':'outbound';}else if(el.id==='compose-direction')composeDirection=el.value;else if(el.id==='prospect-owner'){s().prospectOwners[el.dataset.id]=el.value;persist();toast('Leasing owner updated.');}else return false;render();if(draft&&document.getElementById('communication-form'))for(const name of ['subject','body','minutes','outcome']){const field=document.querySelector(`#communication-form [name="${name}"]`);if(field&&draft[name]!==undefined)field.value=draft[name];}return true;},
  input(el){if(el.id!=='pipeline-search')return false;search=el.value;page=0;const pos=el.selectionStart;render();const input=document.getElementById('pipeline-search');input.focus();input.setSelectionRange(pos,pos);return true;},
  submit(event){const form=event.target;if(!['communication-form','tour-form'].includes(form.id))return false;event.preventDefault();const values=Object.fromEntries(new FormData(form));try{if(form.id==='communication-form'){addInteraction(s(),{...values,leadId:form.dataset.id,duration:Number(values.minutes||0)*60});persist();recordTab='timeline';channel=direction='all';render();toast('Demo interaction recorded. Contact totals updated.');}else{scheduleTour(s(),form.dataset.id,values);persist();render();toast('Demo tour booked and confirmation recorded.');}}catch(error){document.getElementById(form.id==='communication-form'?'communication-error':'tour-error').textContent=error.message;}return true;}
 };
}
